pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address newOwner = address(0x123);
        // c is deployed with msg.sender = address(this), i.e., the test contract
        address initialOwner = c.owner();
        // Act as admin (which is the deployer, address(this)) to call setOwner
        vm.prank(address(this));
        c.setOwner(newOwner);
        // In reference, owner updates to newOwner; in buggy, owner stays as initialOwner
        address finalOwner = c.owner();
        assertTrue(finalOwner != initialOwner, "Owner should have changed after setOwner");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address initialOwner = c.owner();
        address admin = address(this);
        address newOwner = address(0x1234);

        // Admin calls setOwner – reference succeeds, buggy reverts
        bool success = true;
        try c.setOwner(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // In reference: success is true, owner changed to newOwner
        // In bug: success is false, owner unchanged
        assertTrue(success && c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonAdmin = address(0x123);
        address newOwner = address(0x456);

        // nonAdmin tries to set owner
        vm.prank(nonAdmin);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // reference: only admin can set owner so it reverts (ok == false)
        // buggy: any caller succeeds (ok == true)
        assertTrue(ok == false, "Non-admin should not be able to set owner");
    }
}

